text = ("During `distill`, branch-limited runs must not overwrite `manifest.Sources.Facts` "
        "with only touched-branch data; manifest reconstruction is now done from the full "
        "on-disk fact-store using `loadAllFactBranches` plus `countFactProposals` so other "
        "branches and their counts/proposals remain intact.")

# faithful port of locusIdentifierPattern + backtick spans from facts_locus.go
ident = re.compile(r'[A-Za-z_][A-Za-z0-9_]*(?:[./][A-Za-z0-9_]+)+|[A-Za-z_]*[a-z][A-Za-z0-9]*[A-Z][A-Za-z0-9_]*|[A-Za-z][A-Za-z0-9]*_[A-Za-z0-9_]+')
backtick = re.compile(r'`([^`]+)`')

s=set()
def add(t):
    t=t.strip("`.,;:()[]{}'\"").lower()
    if len(t)>=3: s.add(t)
for span in backtick.findall(text):
    for tok in span.split(): add(tok)
for tok in ident.findall(text): add(tok)
print("derived locus tokens:")
for t in sorted(s): print("  ", t)
