105	// inferFactKind deterministically classifies a fact's KIND from its taxonomy
106	// paths (the prior) refined by a few high-precision text cues. This is the
107	// no-agent backfill path and the fallback when the agent omits/violates the
108	// kind; it is heuristic by design — B4's eval is the guardrail. A gotcha cue
109	// wins over everything (a constraint phrased as a trap is a gotcha); otherwise
110	// the highest-priority kind across the fact's paths wins, so the invariant
111	// signal of a `constraints.*` path is never lost to an alphabetically-earlier
112	// co-tag. Allocates nothing — the hot read path calls this per fact.
113	func inferFactKind(paths []string, text string) string {
114		lower := strings.ToLower(text)
115		for _, cue := range gotchaCues {
116			if strings.Contains(lower, cue) {
117				return factKindGotcha
118			}
119		}
120		best := ""
121		for _, p := range paths {
122			if k := topLevelToKind(factTopLevel(p)); k != "" && (best == "" || factKindPriority[k] > factKindPriority[best]) {
123				best = k
124			}
125		}
126		if best != "" {
