	kind := rest[:colon]
	if !semanticKindInSet(kind, kindSet) {
		return semanticRecord{}, false
	}
	name := rest[colon+1:]
	if name == "" {
		name = id
	}
	return semanticRecord{RecordType: "external", ID: id, Kind: kind, Name: name, QualifiedName: name}, true
}

